INSERT INTO material(disciplina_id,assunto_id,titulo,descricao,tipo,referencia_externa,fonte_monitor_virtual,disponivel_para_pratica,autorizacao_professor) SELECT d.id,(SELECT id FROM assunto WHERE disciplina_id=d.id AND slug='fundamentos_c'),'Fundamentos da linguagem C','Material teórico para Monitor e geração de questões de estudo.','SLIDE_AULA','local:materiais_academicos/periodo_02/estrutura_de_dados/UNIT_EDD_01_Linguagem_C.pdf',TRUE,FALSE,FALSE FROM disciplina d WHERE slug='estrutura_de_dados' AND NOT EXISTS(SELECT 1 FROM material m WHERE m.disciplina_id=d.id AND m.referencia_externa='local:materiais_academicos/periodo_02/estrutura_de_dados/UNIT_EDD_01_Linguagem_C.pdf');
